def rotate_right(values, k):
    if not values:
        return []
    k %= len(values)
    return values[-k:] + values[:-k] if k else values[:]

def deduplicate_sorted(values):
    result = []
    for value in values:
        if not result or result[-1] != value:
            result.append(value)
    return result

def merge_sorted(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]

def max_subarray_sum(values):
    if not values:
        return 0
    best = current = values[0]
    for value in values[1:]:
        current = max(value, current + value)
        best = max(best, current)
    return best

def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals)
    result = [ordered[0][:]]
    for start, end in ordered[1:]:
        if start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)
        else:
            result.append([start, end])
    return result

def binary_search(values, target):
    left, right = 0, len(values) - 1
    while left <= right:
        middle = (left + right) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle - 1
    return -1

def is_palindrome(text):
    lowered = text.lower()
    return lowered == lowered[::-1]

def first_unique_index(text):
    counts = {}
    for character in text:
        counts[character] = counts.get(character, 0) + 1
    for index, character in enumerate(text):
        if counts[character] == 1:
            return index
    return -1

def longest_unique_length(text):
    last_seen = {}
    start = best = 0
    for index, character in enumerate(text):
        if character in last_seen and last_seen[character] >= start:
            start = last_seen[character] + 1
        last_seen[character] = index
        best = max(best, index - start + 1)
    return best

def lcs_length(first, second):
    row = [0] * (len(second) + 1)
    for left in first:
        previous = 0
        for j, right in enumerate(second, 1):
            saved = row[j]
            if left == right:
                row[j] = previous + 1
            else:
                row[j] = max(row[j], row[j - 1])
            previous = saved
    return row[-1]

def valid_brackets(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for character in text:
        if character in '([{':
            stack.append(character)
        elif not stack or stack.pop() != pairs.get(character):
            return False
    return not stack

def minimum_window(text, pattern):
    need = {}
    for character in pattern:
        need[character] = need.get(character, 0) + 1
    have = {}
    formed = left = 0
    best = None
    for right, character in enumerate(text):
        have[character] = have.get(character, 0) + 1
        if character in need and have[character] == need[character]:
            formed += 1
        while formed == len(need):
            candidate = (right - left + 1, left, right + 1)
            if best is None or candidate[0] < best[0]:
                best = candidate
            outgoing = text[left]
            have[outgoing] -= 1
            if outgoing in need and have[outgoing] < need[outgoing]:
                formed -= 1
            left += 1
    return '' if best is None else text[best[1]:best[2]]

def frequencies(values):
    result = {}
    for value in values:
        result[value] = result.get(value, 0) + 1
    return result

def has_pair_sum(values, target):
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return True
        if total < target:
            left += 1
        else:
            right -= 1
    return False

def two_sum(values, target):
    seen = {}
    for index, value in enumerate(values):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    return []

def sorted_squares(values):
    result = [0] * len(values)
    left, right = 0, len(values) - 1
    for index in range(len(values) - 1, -1, -1):
        if abs(values[left]) > abs(values[right]):
            result[index] = values[left] ** 2; left += 1
        else:
            result[index] = values[right] ** 2; right -= 1
    return result

def majority_value(values):
    candidate = count = 0
    for value in values:
        if count == 0:
            candidate = value
        count += 1 if value == candidate else -1
    return candidate

def longest_at_most_k(values, k):
    if k <= 0:
        return 0
    counts = {}
    left = best = 0
    for right, value in enumerate(values):
        counts[value] = counts.get(value, 0) + 1
        while len(counts) > k:
            outgoing = values[left]
            counts[outgoing] -= 1
            if counts[outgoing] == 0:
                del counts[outgoing]
            left += 1
        best = max(best, right - left + 1)
    return best

def count_subarrays_sum(values, k):
    counts = {0: 1}
    total = result = 0
    for value in values:
        total += value
        result += counts.get(total - k, 0)
        counts[total] = counts.get(total, 0) + 1
    return result

def three_sum_zero(values):
    values = sorted(values)
    result = []
    for i in range(len(values) - 2):
        if i and values[i] == values[i - 1]:
            continue
        left, right = i + 1, len(values) - 1
        while left < right:
            total = values[i] + values[left] + values[right]
            if total == 0:
                result.append([values[i], values[left], values[right]])
                left += 1; right -= 1
                while left < right and values[left] == values[left - 1]: left += 1
                while left < right and values[right] == values[right + 1]: right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1
    return result

def word_ladder_length(begin, end, words):
    dictionary = set(words)
    if end != begin and end not in dictionary:
        return 0
    queue = [(begin, 1)]
    seen = {begin}
    for word, distance in queue:
        if word == end:
            return distance
        for index in range(len(word)):
            for letter in 'abcdefghijklmnopqrstuvwxyz':
                candidate = word[:index] + letter + word[index + 1:]
                if candidate in dictionary and candidate not in seen:
                    seen.add(candidate)
                    queue.append((candidate, distance + 1))
    return 0
